public class HistogramPrinterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + quote(expected) + " but got " + quote(actual));
            failures++;
        }
    }

    static String quote(Object value) {
        if (value == null) {
            return "null";
        }
        return "\"" + value.toString().replace("\n", "\\n") + "\"";
    }

    static String capture(String[] labels, int[] counts) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            HistogramPrinter.printHistogram(labels, counts);
        } catch (RuntimeException ex) {
            System.setOut(old);
            return "threw " + ex;
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        check("three fruits",
                "apples|*****\nfigs  |\nkiwi  |***\n",
                capture(new String[] {"apples", "figs", "kiwi"}, new int[] {5, 0, 3}));
        check("longest label sets the width",
                "a        |*\nblueberry|**\n",
                capture(new String[] {"a", "blueberry"}, new int[] {1, 2}));
        check("single entry", "mon|****\n", capture(new String[] {"mon"}, new int[] {4}));
        check("negative count draws no stars",
                "up  |**\ndown|\n",
                capture(new String[] {"up", "down"}, new int[] {2, -3}));
        check("empty arrays print nothing", "", capture(new String[] {}, new int[] {}));
        check("zero count line ends at the bar", "x|\n", capture(new String[] {"x"}, new int[] {0}));

        String out = capture(new String[] {"alpha", "be"}, new int[] {3, 1});
        String[] lines = out.split("\n", -1);
        check("line count", 2, lines.length - 1);
        check("second line padded to 5", "be   |*", lines.length > 1 ? lines[1] : "");

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

