public class HistogramPrinter {

    public static void printHistogram(String[] labels, int[] counts) {
        int width = 0;
        for (String label : labels) {
            if (label.length() > width) {
                width = label.length();
            }
        }
        for (int i = 0; i < labels.length; i++) {
            System.out.print(String.format("%-" + width + "s", labels[i]));
            System.out.print("|");
            for (int star = 0; star < counts[i]; star++) {
                System.out.print("*");
            }
            System.out.println();
        }
    }
}
